import std.concurrent as conc

pub type AppError = Failed(String)

fn join(t: conc.TaskHandle<Int64>) -> Int64 {
    let r = t.await()
    return match r {
        Ok(v) => v
        Err(conc.Panicked(m)) => 0
    }
}

pub fn main() -> Result<(), AppError> {
    return Ok(())
}

